"use client";

import { useState } from "react";
import { Check, Copy, RotateCcw } from "lucide-react";
import type { ChatAttachment } from "@/lib/ai/chat-attachments";
import type { ChatItem } from "./chat-messages";

export const RESEND_EVENT = "moneo-chat-resend";
export type Resend = { message: string; attachments: ChatAttachment[] };

export function resendQuestion(messages: ChatItem[], index: number): Resend | null {
  const question = messages.slice(0, index).findLast(item => item.role === "user");
  return question ? { message: question.content, attachments: question.attachments ?? [] } : null;
}

export function MessageActions({ content, model, resend }: { content: string; model?: string; resend: Resend | null }) {
  const [copied, setCopied] = useState(false);
  const button = "flex size-11 items-center justify-center rounded-lg hover:bg-muted hover:text-foreground lg:size-8";
  return <div className="mt-2 flex items-center gap-0.5 text-muted-foreground">
    <button type="button" aria-label="Copy message" title="Copy" className={button} onClick={async () => {
      try { await navigator.clipboard.writeText(content); setCopied(true); } catch { setCopied(false); }
    }}>{copied ? <Check className="size-4" aria-hidden="true" /> : <Copy className="size-4" aria-hidden="true" />}</button>
    {resend && <button type="button" aria-label="Regenerate reply" title="Regenerate" className={button} onClick={() => window.dispatchEvent(new CustomEvent(RESEND_EVENT, { detail: resend }))}><RotateCcw className="size-4" aria-hidden="true" /></button>}
    {model && <span className="ml-1.5 min-w-0 truncate text-xs"><span className="sr-only">Model: </span>{model}</span>}
  </div>;
}
import { expect, it } from "vitest";
import { renderToStaticMarkup } from "react-dom/server";
import { ChatMessages, type ChatItem } from "./chat-messages";
import type { ChatAttachment } from "@/lib/ai/chat-attachments";
import { resendQuestion } from "./message-actions";

const attachment: ChatAttachment = { name: "statement.pdf", path: "ws/statement.pdf", type: "application/pdf" };
const messages: ChatItem[] = [
  { id: "q1", role: "user", content: "First question", created_at: "t" },
  { id: "a1", role: "assistant", content: "First answer", created_at: "t" },
  { id: "q2", role: "user", content: "Second question", created_at: "t", attachments: [attachment] },
  { id: "a2", role: "assistant", content: "Second answer", created_at: "t", model: "gpt-test-1" },
];

it("regenerate resends the question behind that reply, with its attachments", () => {
  expect(resendQuestion(messages, 3)).toEqual({ message: "Second question", attachments: [attachment] });
  expect(resendQuestion(messages, 1)).toEqual({ message: "First question", attachments: [] });
});

it("shows the model that produced a reply", () => {
  expect(renderToStaticMarkup(<ChatMessages messages={messages} />)).toContain("gpt-test-1");
});
"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { selectConversation } from "@/lib/ai/selected-conversation";
import { useChatRequest, type ChatAnswer, type ChatStreamEvent } from "@/lib/ai/use-chat-request";
import { useChatQueue } from "@/lib/ai/use-chat-queue";
import { useChatAttachments } from "@/lib/ai/use-chat-attachments";
import { ATTACHMENT_ONLY_MESSAGE, type ChatAttachment } from "@/lib/ai/chat-attachments";
import { ChatComposer, withSpoken } from "@/components/chat-composer";
import { VOICE_CONTEXT } from "@/lib/ai/voice-context";
import { ChatQueue } from "@/components/chat-queue";
import { DRAFT_EVENT } from "@/components/chat-messages";
import { RESEND_EVENT, type Resend } from "@/components/message-actions";

const suggestions = ["What changed in my spending last month?", "Where did most of my money go this month?", "Find my largest transactions", "Create a spending chart"];

export type ChatFormEvents = {
  onStart?: (conversationId: string, question: string, attachments: ChatAttachment[], spoken: boolean) => void;
  onEvent?: (conversationId: string, event: ChatStreamEvent) => void;
  onDone?: (conversationId: string, question: string, result: ChatAnswer | null, attachments: ChatAttachment[]) => void;
};

export function ChatForm({ conversationId, selectionKey, empty = false, scope, placeholder = "Ask anything about your money", autoSend, onStart, onEvent, onDone }: { conversationId: string; selectionKey: string; isNewConversation?: boolean; empty?: boolean; scope?: React.ReactNode; placeholder?: string; autoSend?: string } & ChatFormEvents) {
  const [message, setMessage] = useState("");
  const draftKey = `moneo-chat-draft:${conversationId}`;
  const draftLoaded = useRef(false);
  useEffect(() => {
    try {
      if (draftLoaded.current) { if (message) sessionStorage.setItem(draftKey, message); else sessionStorage.removeItem(draftKey); return; }
      draftLoaded.current = true;
      const saved = sessionStorage.getItem(draftKey);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      if (saved) setMessage(current => current || saved);
    } catch {}
  }, [message, draftKey]);
  const chat = useChatRequest();
  const files = useChatAttachments();
  const { send, cancel, busy, error, status } = chat;
  useEffect(() => {
    const draft = (event: Event) => { const detail = (event as CustomEvent<{ prompt?: string; compact: boolean }>).detail; if (!detail.compact && detail.prompt) { setMessage(detail.prompt); document.getElementById("question")?.focus(); } };
    window.addEventListener(DRAFT_EVENT, draft);
    return () => window.removeEventListener(DRAFT_EVENT, draft);
  }, []);

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!message.trim() && !files.ready.length) return;
    if (busy) { if (files.items.length) return; enqueue(message); setMessage(""); return; }
    void sendMessage(message, false, files.ready);
  }

  function sendSpoken(text: string) {
    const typed = withSpoken(message, text);
    if (files.uploading || files.items.some(item => item.error) || (busy && files.items.length)) { setMessage(typed); document.getElementById("question")?.focus(); return; }
    if (busy) { enqueue(typed); setMessage(""); return; }
    void sendMessage(typed, false, files.ready, true);
  }

  async function sendMessage(typed: string, queued = false, attachments: ChatAttachment[] = [], spoken = false) {
    if (busy) return;
    const message = typed.trim() || ATTACHMENT_ONLY_MESSAGE;
    onStart?.(conversationId, message, attachments, spoken);
    if (!queued) { setMessage(""); files.clear(); }
    const result = await send({ conversationId, message, ...(spoken && { context: VOICE_CONTEXT }), ...(attachments.length && { attachments }) }, streamed => onEvent?.(conversationId, withSteers(streamed)));
    if (result) {
      selectConversation(selectionKey, conversationId);
    } else if (!queued) { setMessage(current => current || typed); files.restore(attachments); }
    onDone?.(conversationId, message, result, attachments);
  }

  function startQueued(next: string) {
    if (busy) return false;
    void sendMessage(next, true);
    return true;
  }
  const { queue, enqueue, remove, steer, withSteers, canSteer } = useChatQueue(chat, conversationId, startQueued);

  const autoSent = useRef<string | undefined>(undefined);
  useEffect(() => {
    if (!autoSend) { autoSent.current = undefined; return; }
    if (autoSent.current === autoSend) return;
    autoSent.current = autoSend;
    void sendMessage(autoSend);
  });
  useEffect(() => {
    const resend = (event: Event) => { const detail = (event as CustomEvent<Resend>).detail; void sendMessage(detail.message, true, detail.attachments); };
    window.addEventListener(RESEND_EVENT, resend);
    return () => window.removeEventListener(RESEND_EVENT, resend);
  });

  const composer = <><ChatQueue items={queue} canSteer={canSteer} onSteer={item => void steer(item)} onRemove={remove} /><ChatComposer id="question" label="Ask about your finances" value={message} onChange={setMessage} onSubmit={submit} onStop={() => void cancel()} busy={busy} placeholder={placeholder} busyText="Working on a reply. Anything you send now is queued." attachments={files} voice={{ onSend: sendSpoken }} /></>;
  const notices = <>{error && <p role="alert" className="mt-2 px-3 text-sm text-danger">{error}</p>}
    {status === "canceled" && <p role="status" className="mt-2 px-3 text-sm text-muted-foreground">Canceled. Previously completed edits remain in transaction history.</p>}</>;

  if (empty) return <div className="flex flex-1 flex-col justify-center py-10 max-lg:pt-6 max-lg:pb-0">
    <h2 className="text-center font-display text-3xl font-semibold tracking-tight max-lg:mt-auto max-lg:text-2xl sm:text-4xl">How can I help with your money today?</h2>
    <div className="mt-8 max-lg:sticky max-lg:bottom-0 max-lg:order-last max-lg:mt-6 max-lg:bg-background max-lg:pt-2 max-lg:pb-[calc(0.5rem+env(safe-area-inset-bottom))]">{composer}{notices}</div>
    <div className="mt-4 flex flex-wrap justify-center gap-2 max-lg:mt-6">{suggestions.map(prompt => <button key={prompt} type="button" onClick={() => { setMessage(prompt); document.getElementById("question")?.focus(); }} className="rounded-full border border-border px-3.5 py-2 text-sm text-muted-foreground hover:bg-muted hover:text-foreground active:bg-muted">{prompt}</button>)}</div>
    <p className="mx-auto mt-6 max-w-xl text-center text-xs text-muted-foreground">Ask here for a quick answer. Run a deep review for a saved, evidence-checked report. Call to talk it through. Each one uses AI, tracked under <Link href="/settings" className="underline">Settings</Link>.</p>
    <div className="max-lg:mb-auto">{scope}</div>
  </div>;

  return <div className="sticky bottom-0 mt-auto bg-gradient-to-t from-background from-70% to-transparent pt-6 pb-4 max-lg:pb-[calc(0.5rem+env(safe-area-inset-bottom))]">{composer}{notices}{scope}</div>;
}
import type { ChatAttachment } from "./chat-attachments";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { awaitedLater } from "@/lib/awaited-later";
import { isSpoken } from "./voice-context";
import { callStubs, loadCalls, type CallCard } from "./voice-call-history";

const cursorSchema = z.object({ created_at: z.iso.datetime({ offset: true }), id: z.uuid() });
export type HistoryMessage = { id: string; role: string; content: string; created_at: string; plan?: string[]; tools?: SavedToolStep[]; model?: string; attachments?: ChatAttachment[]; spoken?: boolean; call?: CallCard };
export type SavedToolStep = { name: string; state: "done"; input?: unknown; output?: string };
export type HistoryThread = { id: string; title: string; created_at: string };
const THREAD_PAGE = 30;
const MESSAGE_PAGE = 30;
const OUTPUT_PREVIEW = 2000;
const preview = (output?: string) => output && output.length > OUTPUT_PREVIEW ? `${output.slice(0, OUTPUT_PREVIEW)}\n… (truncated)` : output;
const RUN_WINDOW_MS = 6 * 60_000;
export const conversationTitleSchema = z.string().trim().min(1).max(120);

function before(value?: string) {
  if (!value) return null;
  try { return cursorSchema.parse(JSON.parse(value)); } catch { throw new Error("Invalid history cursor"); }
}
function cursor(row: { id: string; created_at: string }) { return JSON.stringify({ id: row.id, created_at: row.created_at }); }
function likePattern(query: string) { return `%${query.replace(/[\\%_]/g, "\\$&").replaceAll("*", "_")}%`; }

export async function loadThreads(supabase: SupabaseClient, workspace: string, threadsBefore?: string, query?: string) {
  const live = () => supabase.from("conversations").select("id,title,created_at").eq("workspace_id", workspace).is("deleted_at", null).is("artifact_id", null);
  const q = query?.trim().slice(0, 100);
  if (q) {
    const pattern = likePattern(q);
    const [titles, hits] = await Promise.all([
      live().ilike("title", pattern).order("created_at", { ascending: false }).limit(THREAD_PAGE),
      supabase.from("messages").select("conversation_id").eq("workspace_id", workspace).ilike("content", pattern).order("created_at", { ascending: false }).limit(200),
    ]);
    if (titles.error || hits.error) throw new Error("Could not search conversations. Try again.");
    const known = new Set((titles.data ?? []).map(row => row.id));
    const extra = [...new Set((hits.data ?? []).map(row => row.conversation_id as string))].filter(id => !known.has(id)).slice(0, THREAD_PAGE);
    const matched = extra.length ? await live().in("id", extra) : { data: [], error: null };
    if (matched.error) throw new Error("Could not search conversations. Try again.");
    const threads = [...(titles.data ?? []), ...(matched.data ?? [])]
      .sort((a, b) => b.created_at.localeCompare(a.created_at)).slice(0, THREAD_PAGE) as HistoryThread[];
    return { threads, threadsCursor: null };
  }
  const tc = before(threadsBefore);
  let tq = live().order("created_at", { ascending: false }).order("id", { ascending: false });
  if (tc) tq = tq.or(`created_at.lt.${tc.created_at},and(created_at.eq.${tc.created_at},id.lt.${tc.id})`);
  const { data, error } = await tq.limit(THREAD_PAGE + 1);
  if (error) throw new Error("Could not load conversations. Try again.");
  const threads = (data ?? []).slice(0, THREAD_PAGE) as HistoryThread[];
  return { threads, threadsCursor: (data?.length ?? 0) > THREAD_PAGE ? cursor(threads[threads.length - 1]) : null };
}

export async function loadConversation(supabase: SupabaseClient, workspace: string, id: string, messagesBefore?: string) {
  const mc = before(messagesBefore);
  if (!z.uuid().safeParse(id).success) throw new Error("Conversation unavailable");
  let mq = supabase.from("messages").select("id,role,content,created_at,request_id,reply_to,attachments,context").eq("workspace_id", workspace).eq("conversation_id", id).order("created_at", { ascending: false }).order("id", { ascending: false });
  if (mc) mq = mq.or(`created_at.lt.${mc.created_at},and(created_at.eq.${mc.created_at},id.lt.${mc.id})`);
  const [conversation, page, run, stubs] = await Promise.all([
    supabase.from("conversations").select("id,title,created_at").eq("workspace_id", workspace).eq("id", id).is("deleted_at", null).maybeSingle(),
    mq.limit(MESSAGE_PAGE + 1),
    mc ? null : supabase.from("chat_requests").select("id,created_at").eq("workspace_id", workspace).eq("conversation_id", id).eq("status", "running")
      .order("created_at", { ascending: false }).limit(1).maybeSingle(),
    callStubs(supabase, workspace, id),
  ]);
  if (conversation.error) throw new Error("Could not load conversation. Try again.");
  if (!conversation.data) throw new Error("Conversation unavailable. It may be missing or belong to another workspace.");
  if (page.error) throw new Error("Could not load messages. Try again.");
  const rows = (page.data ?? []).slice(0, MESSAGE_PAGE) as (HistoryMessage & { request_id?: string | null; reply_to?: string | null; context?: unknown })[];
  const messagesCursor = (page.data?.length ?? 0) > MESSAGE_PAGE ? cursor(rows[rows.length - 1]) : null;
  const calls = await loadCalls(supabase, workspace, id, stubs, { requestIds: rows.flatMap(row => row.request_id ?? row.reply_to ?? []),
    from: messagesCursor ? rows[rows.length - 1].created_at : undefined, to: mc?.created_at });
  const visible = rows.filter(row => !calls.hidden.has((row.request_id ?? row.reply_to) as string));
  const activity = await savedActivity(supabase, workspace, visible.flatMap(row => row.role === "assistant" && row.reply_to ? [row.reply_to] : []));
  const messages: HistoryMessage[] = [...visible.map(({ reply_to, context, ...message }) => ({ ...message, request_id: undefined, ...(isSpoken(context) && { spoken: true }), ...(reply_to ? activity.get(reply_to) : undefined) })), ...calls.items]
    .sort((a, b) => b.created_at.localeCompare(a.created_at));
  const latest = run?.data as { id: string; created_at: string } | null | undefined;
  const running = latest && Date.parse(latest.created_at) > Date.now() - RUN_WINDOW_MS ? latest.id : null;
  return { selected: conversation.data as HistoryThread, messages: messages.reverse(), messagesCursor, running };
}

const savedCall = z.object({ name: z.string(), input: z.unknown().optional(), output: z.string().optional() });
const planSteps = z.object({ steps: z.array(z.string()) });
const savedUsage = z.object({ model_id: z.string().min(1).max(200) });

async function savedActivity(supabase: SupabaseClient, workspace: string, requestIds: string[]) {
  const activity = new Map<string, { plan?: string[]; tools?: SavedToolStep[]; model?: string }>();
  if (!requestIds.length) return activity;
  const { data, error } = await supabase.from("chat_requests").select("id,tool_calls,usage").eq("workspace_id", workspace).in("id", requestIds);
  if (error) return activity;
  for (const row of (data ?? []) as { id: string; tool_calls: unknown; usage: unknown }[]) {
    const model = savedUsage.safeParse(row.usage).data?.model_id;
    const parsed = z.array(savedCall).safeParse(row.tool_calls);
    const calls = parsed.success ? parsed.data : [];
    const plan = calls.flatMap(call => call.name === "plan_investigation" ? [planSteps.safeParse(call.input)] : []).find(found => found.success)?.data?.steps;
    const tools = calls.filter(call => call.name !== "plan_investigation").map(call => ({ name: call.name, state: "done" as const, input: call.input, output: preview(call.output) }));
    activity.set(row.id, { ...(plan ? { plan } : {}), ...(tools.length ? { tools } : {}), ...(model ? { model } : {}) });
  }
  return activity;
}

export async function loadConversationHistory(supabase: SupabaseClient, workspace: string, requested?: string, threadsBefore?: string, messagesBefore?: string) {
  before(messagesBefore);
  if (requested && requested !== "new" && !z.uuid().safeParse(requested).success) throw new Error("Conversation unavailable");
  const explicit = requested && requested !== "new" ? awaitedLater(loadConversation(supabase, workspace, requested, messagesBefore)) : null;
  const { threads, threadsCursor } = await loadThreads(supabase, workspace, threadsBefore);
  const conversation = await explicit;
  return { threads, threadsCursor, selected: conversation?.selected ?? null, messages: conversation?.messages ?? [], messagesCursor: conversation?.messagesCursor ?? null, running: conversation?.running ?? null };
}
