"use client";

import { useRef, useState } from "react";
import type { FollowUp } from "./follow-ups";
import type { ChatAttachment } from "./chat-attachments";

export type ChatAnswer = { answer: string; conversationId: string; toolsUsed?: string[]; followUps?: FollowUp[]; model?: string };
export type ChatStreamEvent =
  | { type: "started" }
  | { type: "tool"; id?: string; name: string; state: "running" | "done" | "failed"; input?: unknown; output?: string }
  | { type: "plan"; steps: string[] }
  | { type: "steered"; steers: { id: string; content: string }[] }
  | { type: "delta"; text: string }
  | { type: "title"; title: string }
  | ({ type: "answer" } & ChatAnswer)
  | { type: "result"; status: number; body: unknown };

export async function readResponse(response: Response, onEvent: (event: ChatStreamEvent) => void): Promise<{ ok: boolean; status: number; body: { error?: string } & Partial<ChatAnswer> }> {
  if (!response.headers.get("content-type")?.includes("application/x-ndjson") || !response.body) return { ok: response.ok, status: response.status, body: await response.json() };
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  for (;;) {
    const { value, done } = await reader.read();
    buffer += value ?? "";
    const lines = buffer.split("\n");
    buffer = done ? "" : lines.pop()!;
    for (const line of lines.filter(Boolean)) {
      const event = JSON.parse(line) as ChatStreamEvent;
      if (event.type === "result") return { ok: event.status < 400, status: event.status, body: event.body as { error?: string } };
      onEvent(event);
    }
    if (done) throw new Error("The answer stream ended early; reload to see whether it was saved");
  }
}

export function useChatRequest() {
  const active = useRef<{ requestId: string; controller: AbortController } | null>(null);
  const [status, setStatus] = useState<"idle" | "running" | "completed" | "failed" | "canceled">("idle");
  const [error, setError] = useState("");
  const [conversationId, setConversationId] = useState<string | null>(null);

  async function send(payload: { conversationId: string; message: string; context?: Record<string, unknown>; attachments?: ChatAttachment[] }, onEvent?: (event: ChatStreamEvent) => void) {
    if (active.current) return null;
    const run = { requestId: crypto.randomUUID(), controller: new AbortController() };
    active.current = run;
    setConversationId(payload.conversationId);
    setStatus("running");
    setError("");
    try {
      const response = await fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" },
        signal: run.controller.signal, body: JSON.stringify({ ...payload, requestId: run.requestId }) });
      const result = await readResponse(response, event => { if (active.current === run) onEvent?.(event); });
      if (active.current !== run) return null;
      if (!result.ok) throw new Error(result.body.error ?? "Could not answer");
      setStatus("completed");
      return result.body as ChatAnswer;
    } catch (cause) {
      if (active.current === run) { setStatus("failed"); setError(cause instanceof Error ? cause.message : "Could not answer"); }
      return null;
    } finally { if (active.current === run) active.current = null; }
  }

  async function cancel() {
    const run = active.current;
    if (!run) return;
    try {
      let response: Response | undefined;
      for (let attempt = 0; attempt < 10; attempt++) {
        response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId: run.requestId }) });
        if (response.status !== 404) break;
        await new Promise(resolve => setTimeout(resolve, 100));
      }
      const result = await response!.json();
      if (!response!.ok) throw new Error(result.error ?? "Could not cancel; try again");
      if (result.status === "canceled" && active.current === run) {
        active.current = null;
        run.controller.abort();
        setStatus("canceled");
      }
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not cancel; try again"); }
  }

  const requestId = () => active.current?.requestId ?? null;
  return { send, cancel, requestId, status, error, busy: status === "running", conversationId };
}
-- Chat charts can carry exact series resolved from tool data (a year of days), so an answer may be longer than 20,000 characters.
create or replace function public.finish_chat_request(p_request_id uuid,p_status text,p_content text,p_usage jsonb default null,p_tool_calls jsonb default null)
returns text language plpgsql security definer set search_path='' as $$
declare request_row public.chat_requests%rowtype; token_key text;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if p_status is null or p_status not in ('completed','failed') or p_content is null or length(p_content)>200000 then
    raise exception 'Invalid chat completion' using errcode='22023';
  end if;
  if p_usage is not null then
    if jsonb_typeof(p_usage)<>'object' or p_usage - array['model_id','input_tokens','output_tokens','total_tokens'] <> '{}'::jsonb
      or jsonb_typeof(p_usage->'model_id') is distinct from 'string' or length(p_usage->>'model_id') not between 1 and 200 then
      raise exception 'Invalid provider usage' using errcode='22023';
    end if;
    foreach token_key in array array['input_tokens','output_tokens','total_tokens'] loop
      if p_usage ? token_key and p_usage->token_key <> 'null'::jsonb and
        (jsonb_typeof(p_usage->token_key)<>'number' or p_usage->>token_key !~ '^[0-9]+$' or (p_usage->>token_key)::numeric>9007199254740991) then
        raise exception 'Invalid token count' using errcode='22023';
      end if;
    end loop;
  end if;
  -- Each call is {name, input, output} with the output already truncated by the caller.
  if p_tool_calls is not null and (jsonb_typeof(p_tool_calls)<>'array' or jsonb_array_length(p_tool_calls)>100
    or length(p_tool_calls::text)>500000 or exists(select 1 from jsonb_array_elements(p_tool_calls) call
      where jsonb_typeof(call)<>'object' or jsonb_typeof(call->'name') is distinct from 'string')) then
    raise exception 'Invalid tool calls' using errcode='22023';
  end if;
  select * into request_row from public.chat_requests where id=p_request_id and public.owns_workspace(workspace_id) for update;
  if not found then raise exception 'Chat request not found' using errcode='P0002'; end if;
  if request_row.status<>'running' then return request_row.status; end if;
  if p_status='completed' then
    insert into public.messages(workspace_id,conversation_id,role,content,reply_to)
      values(request_row.workspace_id,request_row.conversation_id,'assistant',p_content,p_request_id);
  end if;
  update public.chat_requests set status=p_status,answer=case when p_status='completed' then p_content end,
    error=case when p_status='failed' then left(p_content,500) end,usage=p_usage,tool_calls=p_tool_calls,updated_at=now() where id=p_request_id;
  return p_status;
end;
$$;

